package diag

import (
	"strings"

	typerr "github.com/matjam/plutonium/internal/types2/errors"
)

// The type checker comes from go/types, and so do its error codes and their
// documentation (catalog_go.go, generated by gencatalog). Each code becomes
// a catalog entry: the hand-written plain-words text in goPlain where there
// is one, otherwise the go/types description, with its spec quote and
// first example.

// A goDoc is go/types' documentation of an error code.
type goDoc struct {
	Value    int
	Name     string
	Text     string   // description, paragraphs separated by "\n"
	Spec     string   // a quote from the Go spec, or ""
	Examples []string // code with the error
}

// goSpec names a section of the Go spec that Plutonium follows.
func goSpec(section string) string {
	return "\"" + section + "\" in the Go spec" + goSpecFollows
}

func init() {
	for _, d := range goDocs {
		e := &Entry{Code: CheckerCode(typerr.Code(d.Value)), Name: d.Name}
		if p, ok := goPlain[d.Name]; ok {
			e.Text, e.Fix, e.Spec, e.Example, e.Fixed = p.Text, p.Fix, p.Spec, p.Example, p.Fixed
		} else {
			e.Text = describeDoc(d)
			e.Spec = "the Go spec" + goSpecFollows
		}
		if e.Example == "" && len(d.Examples) > 0 {
			e.Example = d.Examples[0]
		}
		register(e)
	}
}

// describeDoc turns go/types' description of a code into an explanation:
// "UnusedImport occurs when ..." becomes "This error occurs when ...", and
// a quote from the spec follows.
func describeDoc(d goDoc) string {
	text := d.Text
	if rest, ok := strings.CutPrefix(text, d.Name+" "); ok {
		text = "This error " + rest
	}
	if d.Spec != "" {
		text += "\nThe Go spec says: " + d.Spec
	}
	return text
}
